"""A bounded question view on the existing Atlas facts."""
MAP_CSS = r"""
.cm-tabs{display:none}.cm-grid{display:grid;grid-template-columns:220px minmax(220px,1fr) minmax(280px,1fr);gap:18px}.cm-grid>section{min-width:0}.cm-grid button{max-width:100%;white-space:normal;overflow-wrap:anywhere}.cm-grid pre{white-space:pre-wrap;overflow-wrap:anywhere}.cm-nodes{display:block}.cm-nodes[hidden]{display:none}.cm-nodes svg{width:100%;min-height:320px}.cm-nodes foreignObject button{width:100%;height:100%;font-size:12px}.cm-node{border:1px solid var(--line,#ddd);border-radius:8px;padding:12px}.cm-node[aria-pressed=true]{outline:2px solid #3165db}.cm-grid li{margin:8px 0}.cm-form{display:flex;gap:8px;flex-wrap:wrap}.cm-form input{flex:1;min-width:180px}@media(max-width:800px){.cm-tabs{display:flex;gap:8px;margin:16px 0}.cm-tabs button[aria-pressed=true]{outline:2px solid #3165db}.cm-grid{display:block}.cm-grid>section{margin:20px 0;display:none}.cm-grid[data-pane="steps"]>section:nth-child(1),.cm-grid[data-pane="map"]>section:nth-child(2),.cm-grid[data-pane="source"]>section:nth-child(3){display:block}}
"""
MAP_JS = r"""
const cmCall=(operation,args)=>{if(['map_get','maps_list'].includes(operation)){const q=new URLSearchParams(Object.entries(args).filter(([k])=>k!=='project'));return get('/api/projects/'+encodeURIComponent(args.project)+'/maps?'+q)}if(operation==='map_create')return post('/api/projects/'+encodeURIComponent(args.project)+'/maps',args);return api('POST','/api/agent/'+operation,args,{'X-Webuddy-Agent':'web-map'})};
async function vCodeMaps(project=S.proj,id=''){
  const route=location.hash,seq=S.mapRead=(S.mapRead||0)+1,alive=()=>seq===S.mapRead&&location.hash===route;

  setProj(project);paintSel();$('#main').innerHTML='<p role="status">正在读取固定地图…</p>';
  try{
    if(!id){
      const page=await cmCall('maps_list',{project});if(!alive())return;
      $('#main').innerHTML=pageHead('围绕业务问题查代码','',`<a class="btn" href="#/atlas">项目全景</a><a class="btn" href="#/reform">已有业务场景</a>`)+`<form class="cm-form" id="cmQuestion"><label for="cmQ">业务问题</label><input id="cmQ" required placeholder="例如：退款后预算如何退回？"><button>保存局部地图</button></form><p id="cmMessage" role="status"></p><div id="cmSaved">${page.items.map(m=>`<article><a href="#/maps/${encodeURIComponent(project)}/${m.id}">${h(m.question)}</a><p>${h(chinaTime(m.created_at))} · ${h(m.provenance.source_version)}</p></article>`).join('')||'<p>还没有保存的地图。</p>'}</div>`;
      if(page.next_after!=null){const more=document.createElement('button');more.textContent='加载更多已保存地图';$('#cmSaved').after(more);let cursor=page.next_after;more.onclick=async()=>{more.disabled=true;try{const next=await cmCall('maps_list',{project,after:cursor});if(!alive())return;$('#cmSaved').insertAdjacentHTML('beforeend',next.items.map(m=>`<article><a href="#/maps/${encodeURIComponent(project)}/${m.id}">${h(m.question)}</a><p>${h(chinaTime(m.created_at))}</p></article>`).join(''));cursor=next.next_after;if(cursor==null)more.remove()}catch(e){if(alive())$('#cmMessage').textContent=e.message}finally{more.disabled=false}}}
      if(!accessCanWrite(project))$('#cmQuestion').hidden=true;
      const key='webuddy.map-draft.'+project;let draft;try{draft=JSON.parse(sessionStorage.getItem(key)||'null')}catch(e){}
      if(draft)$('#cmQ').value=draft.question;
      $('#cmQ').oninput=()=>{const prior=JSON.parse(sessionStorage.getItem(key)||'{}');sessionStorage.setItem(key,JSON.stringify({...prior,question:$('#cmQ').value}))};
      $('#cmQuestion').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{let saved=JSON.parse(sessionStorage.getItem(key)||'null')||{};if(saved.request_id&&saved.request_question!==$('#cmQ').value)throw Error('上次保存结果待核对，请恢复原问题重试：'+saved.request_question);saved={...saved,question:$('#cmQ').value,request_question:$('#cmQ').value,request_id:saved.request_id||crypto.randomUUID()};sessionStorage.setItem(key,JSON.stringify(saved));const result=await cmCall('map_create',{project,question:saved.question,request_id:saved.request_id});sessionStorage.removeItem(key);if(alive())location.hash='#/maps/'+project+'/'+result.id}catch(err){if(alive())$('#cmMessage').textContent=err.message}finally{if(alive())button.disabled=false}};
      return;
    }
    const m=await cmCall('map_get',{project,map_id:id});if(!alive())return;
    const selected=new Set(),selectKey='webuddy.map-selection.'+project+'.'+id;
    try{for(const n of JSON.parse(sessionStorage.getItem(selectKey)||'[]'))if(m.nodes.some(x=>x.id===n))selected.add(n)}catch(e){}
    $('#main').innerHTML=pageHead(m.question,'',`<a class="btn" href="#/maps/${encodeURIComponent(project)}">已保存地图</a><a class="btn" href="#/atlas">项目全景</a>`)+`<p>地图修订 ${m.revision} · ${h(m.provenance.index_status==='stale'?'生成时索引已过期':'保存的固定来源')} · 当前适用性待核对</p><details><summary>来源、范围与未知项</summary><code>${h(m.provenance.source_version)}</code><p>${h(m.explanation_basis)}</p><p>${h(m.coverage)}；已显示 ${m.nodes.length} 项，已知未展开 ${m.unexpanded.length} 项，来源未解析 ${(m.unknown_nodes||[]).length} 项。</p><p>${h(m.notice)}</p></details><nav class="cm-tabs" aria-label="地图分区"><button data-cm-pane="steps" aria-pressed="true">步骤</button><button data-cm-pane="map" aria-pressed="false">地图</button><button data-cm-pane="source" aria-pressed="false">依据</button></nav><div class="cm-grid" data-pane="steps"><section><h2>相关步骤与规则</h2><p>按检索相关性排列，业务先后待核对。</p><ol>${m.nodes.map(n=>`<li><button data-cm-node="${h(n.id)}">${h(n.label||n.name)}</button></li>`).join('')}</ol></section><section><h2>局部关系</h2><button id="cmToggle">切换为关系列表</button><div class="cm-nodes" id="cmNodes">${m.nodes.map(n=>`<button class="cm-node" data-cm-node="${h(n.id)}" aria-pressed="false">${h(n.label||n.name)}</button>`).join('')||'<p>没有定位到代码。请使用业务词、接口或符号名称补充问题；未调用模型猜测。</p>'}</div><ul id="cmEdges">${m.relations.map((e,i)=>`<li><button data-cm-edge="${i}">${h(e.src)} → ${h(e.dst)} · ${h(e.meaning)}</button></li>`).join('')||'<li>当前范围没有可核对的关系。</li>'}</ul>${m.unexpanded.length?'<button id="cmExpand">展开同一索引范围，另存地图</button>':''}</section><section><h2>依据</h2>${(m.knowledge_references||[]).length?`<details><summary>相关知识引用（${m.knowledge_references.length}）</summary>${m.knowledge_references.map(k=>`<button data-cm-knowledge="${h(k.id)}">${h(k.record.title||k.id)}</button><p>${h(k.record.status||'未确认')}</p><code>${h(k.sha256)}</code><p>${h(k.authority)}</p>`).join('')}</details>`:''}<div id="cmEvidence" role="status">选择节点查看固定源码。</div></section></div><section>${(m.linked_plans||[]).map(p=>`<p><a href="${h(p.deep_link)}">关联改造路线：${h(p.title)} · 修订 ${h(p.revision)}</a> · ${p.tasks.map(t=>`<a href="#/t/${encodeURIComponent(t)}">${h(t)}</a>`).join(' ')}</p>`).join('')}<h2>加入改造草稿</h2><form id="cmAttach"><label>草稿计划编号 <input name="plan" required placeholder="r…"></label><button>把选中节点加入草稿</button></form><p id="cmAttachResult" role="status"></p></section>`;
    if(!accessCanWrite(project)){$('#cmAttach').hidden=true;if($('#cmExpand'))$('#cmExpand').disabled=true}
    function pane(name){$('.cm-grid').dataset.pane=name;document.querySelectorAll('[data-cm-pane]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.cmPane===name)))}
    document.querySelectorAll('[data-cm-pane]').forEach(b=>b.onclick=()=>pane(b.dataset.cmPane));
    function draw(nid){
      const related=m.relations.filter(e=>e.src===nid||e.dst===nid),ids=[nid,...new Set(related.flatMap(e=>[e.src,e.dst]).filter(x=>x!==nid))].slice(0,9),positions={};
      ids.forEach((n,i)=>{positions[n]=i?{x:240+Math.cos((i-1)*Math.PI*2/(ids.length-1))*170,y:200+Math.sin((i-1)*Math.PI*2/(ids.length-1))*160}:{x:240,y:200}});
      const lines=related.filter(e=>positions[e.src]&&positions[e.dst]).map(e=>{const a=positions[e.src],b=positions[e.dst];return `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#94a3b8" ${e.kind==='step'?'stroke-dasharray="4 4"':''}/>`}).join('');
      $('#cmNodes').innerHTML=`<svg viewBox="0 0 480 400" role="img" aria-label="当前节点与已记录的一层关系">${lines}${ids.map(n=>{const p=positions[n],node=m.nodes.find(x=>x.id===n);return `<foreignObject x="${p.x-60}" y="${p.y-25}" width="120" height="50"><button xmlns="http://www.w3.org/1999/xhtml" class="cm-node" data-cm-focus="${h(n)}" aria-pressed="${n===nid}">${h(node?.label||node?.name||n)}</button></foreignObject>`}).join('')}</svg><p>图中 ${ids.length} 项；完整已选范围仍在左侧列表。具体关系与依据见下方列表。</p>`;
      $('#cmEdges').innerHTML=related.map(e=>`<li><button data-cm-focus="${h(e.src===nid?e.dst:e.src)}">${h(e.src)} → ${h(e.dst)} · ${h(e.meaning)}</button></li>`).join('')||'<li>当前节点没有已记录关系。</li>';
      document.querySelectorAll('[data-cm-focus]').forEach(b=>b.onclick=()=>focus(b.dataset.cmFocus));
    }
    async function knowledgeSource(key,line){pane('source');const token=++read;try{const v=await cmCall('map_get',{project,map_id:id,knowledge_id:key,...(line?{line}:{}),limit:60});if(alive()&&token===read){$('#cmEvidence').innerHTML=`<p>${h(v.node.authority)}</p><code>${h(v.node.source_version)}</code><pre>${h(v.text||v.reason)}</pre>${v.next_line?'<button id="cmKnowledgeMore">继续读取这份知识原文</button>':''}`;if(v.next_line)$('#cmKnowledgeMore').onclick=()=>knowledgeSource(key,v.next_line)}}catch(e){if(alive()&&token===read)$('#cmEvidence').textContent=e.message}}
    document.querySelectorAll('[data-cm-knowledge]').forEach(b=>b.onclick=()=>knowledgeSource(b.dataset.cmKnowledge));
    let read=0;
    async function focus(nid,line){pane('source');const token=++read;draw(nid);document.querySelectorAll('[data-cm-node]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.cmNode===nid)));$('#cmEvidence').textContent='正在读取固定源码…';try{const v=await cmCall('map_get',{project,map_id:id,node_id:nid,...(line?{line}:{}),limit:60});if(!alive()||read!==token)return;$('#cmEvidence').innerHTML=`<h3>${h(v.node.label||v.node.name)}</h3><label><input type="checkbox" id="cmSelect" ${selected.has(nid)?'checked':''}> 加入任务上下文</label><p>${h(v.node.file)} · ${h(v.line||v.node.line)} / ${h(v.total_lines||'未知')} 行</p><p>验证覆盖：未由静态地图核验</p>${v.text!=null?`<pre>${h(v.text)}</pre>`:`<p>${h(v.reason)}</p>`}${v.next_line?'<button id="cmMore">继续查看文件</button>':''}`;$('#cmSelect').onchange=e=>{e.target.checked?selected.add(nid):selected.delete(nid);sessionStorage.setItem(selectKey,JSON.stringify([...selected]))};if(v.next_line)$('#cmMore').onclick=()=>focus(nid,v.next_line)}catch(e){if(alive()&&read===token)$('#cmEvidence').textContent=e.message}}
    document.querySelectorAll('[data-cm-node]').forEach(b=>b.onclick=()=>focus(b.dataset.cmNode));document.querySelectorAll('[data-cm-edge]').forEach(b=>b.onclick=()=>focus(m.relations[Number(b.dataset.cmEdge)].src));
    if(m.nodes.length)draw(m.nodes[0].id);
    $('#cmToggle').onclick=()=>{$('#cmNodes').hidden=!$('#cmNodes').hidden;$('#cmToggle').textContent=$('#cmNodes').hidden?'显示节点视图':'切换为关系列表'};
    if($('#cmExpand'))$('#cmExpand').onclick=async e=>{e.target.disabled=true;try{const key=selectKey+'.expand';let pending=JSON.parse(sessionStorage.getItem(key)||'null');pending=pending||{project,question:m.question,from_map:id,limit:60,request_id:crypto.randomUUID()};sessionStorage.setItem(key,JSON.stringify(pending));const next=await cmCall('map_create',pending);sessionStorage.removeItem(key);if(alive())location.hash='#/maps/'+project+'/'+next.id}catch(err){if(alive())$('#cmEvidence').textContent=err.message}finally{if(alive())e.target.disabled=false}};
    $('#cmAttach').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{if(!selected.size)throw Error('先选择要交接的节点');const plan=e.target.elements.plan.value.trim();const original=await cmCall('reform_get',{project,plan_id:plan,view:'scope'});const refs=original.scope.map_refs||[];const requestKey=selectKey+'.attach',prior=JSON.parse(sessionStorage.getItem(requestKey)||'null');const body={project,plan_id:plan,expected_revision:original.revision,request_id:crypto.randomUUID(),reason:'加入已选固定地图上下文',changes:{map_refs:[...refs.filter(r=>r.map_id!==id),{map_id:id,revision:m.revision,nodes:[...selected]}]}};if(prior&&(prior.plan_id!==plan||JSON.stringify(prior.changes)!==JSON.stringify(body.changes)))throw Error('上次交接待核对，请恢复原计划和节点选择');const pending=prior||body;sessionStorage.setItem(requestKey,JSON.stringify(pending));const result=await cmCall('reform_update',pending);sessionStorage.removeItem(requestKey);const checked=await cmCall('reform_get',{project,plan_id:plan,view:'scope'});if(!(checked.scope.map_refs||[]).some(r=>r.map_id===id&&JSON.stringify(r.nodes)===JSON.stringify([...selected])))throw Error('交接回执已保存，但当前草稿引用不同；请进入计划核对最新修订');if(alive())$('#cmAttachResult').innerHTML=`已保存草稿修订 ${h(result.revision)}。<a href="#/projects/${project}/reforms/${plan}">查看改造路线与执行条件</a>`}catch(err){if(alive())$('#cmAttachResult').textContent=err.message}finally{if(alive())button.disabled=false}};
  }catch(e){if(alive())$('#main').innerHTML=`<h2>地图暂不可读</h2><p role="alert">${h(e.message)}</p><a href="#/maps/${encodeURIComponent(project)}">返回地图列表</a>`}
}
"""
